-- Fills in client_description, coach_cues, primary_muscle_group,
-- movement_type, and laterality for the exercises used in the
-- hand-authored programs (General Population, Postpartum Recovery,
-- Senior/Fall-Prevention, Medically Conservative, Chronic Illness
-- Support, Rehab-Forward) that were seeded name-only, plus a handful
-- of PNF/combo exercises missing a muscle group. This is the same
-- kind of systematic, movement-pattern-and-equipment-based drafting
-- as migration 0044 did for the 965 bulk-imported exercises, not
-- independently researched per exercise -- review in the Library
-- before leaning on it clinically, same as any AI-drafted content.
--
-- coalesce() on every column means this only fills genuinely blank
-- fields -- it never overwrites a description, cue, or muscle group
-- already written (by hand or by an earlier migration) on any
-- exercise, including the ones this same file also touches.
update public.exercises e
set
  client_description = coalesce(e.client_description, v.description),
  coach_cues = coalesce(e.coach_cues, v.cues),
  primary_muscle_group = coalesce(e.primary_muscle_group, v.muscle_group),
  movement_type = coalesce(e.movement_type, v.movement_type),
  laterality = coalesce(e.laterality, v.laterality)
from (values
  ('Ab/Core: Ball Slams -- AMRAP 30 sec', 'Slam a medicine ball into the floor as hard as you can and reset, for as many reps as you can in 30 seconds -- a full-body power move that doubles as a core and conditioning finisher.', 'Reach fully overhead before every slam; drive the slam with the core and hips, not just the arms; catch the bounce and reset your stance each rep.', 'Core', 'compound', 'bilateral'),
  ('Ab/Core: Bird Dog (pain-free range)', 'The standard Bird Dog, kept inside whatever range feels completely pain-free -- extend the opposite arm and leg only as far as you can without discomfort or losing a flat back.', 'Stop the extension the moment you feel any pain or the low back starts to move; a smaller, controlled range here is the point, not a limitation.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Bird Dog + Dead Bug', 'Bird Dog and Dead Bug performed back to back as a pair -- one from hands and knees, one on your back -- to hit anti-rotation and anti-extension core control from two angles.', 'Keep the low back flat and still through both movements; move slow and controlled, not fast; a small range done well beats a big range that lets the back sag.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Bird Dog to Elbow-Knee + Glute Bridge March', 'A combo set: Bird Dogs that bring the extended elbow and knee together underneath you, followed by a Glute Bridge held while marching the knees up one at a time.', 'On the Bird Dog portion, control the tuck-in as much as the reach-out; on the bridge march, keep the hips level and still as each knee lifts -- don''t let them dip.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Dead Bug (DB) + Leg Raise', 'Dead Bug performed holding a light dumbbell overhead, paired with a straight-leg raise -- adds an anti-extension load challenge on top of the base Dead Bug pattern.', 'Press the low back flat into the floor and keep it there the whole set; lower the arm/leg only as far as that contact holds; keep the dumbbell arm steady overhead.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Dead Bug (pain-free range)', 'The standard Dead Bug, kept inside whatever range feels completely pain-free -- lower the opposite arm and leg only as far as you can without discomfort or the low back lifting off the floor.', 'Stop the lowering the moment you feel any pain or the low back starts to arch off the floor; a smaller, controlled range here is the point.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Dead Bug + 90/90 Breathing', 'Dead Bug paired with 90/90 positional breathing -- hips and knees stacked at 90 degrees, focusing on a full exhale to reset core/diaphragm control before or between Dead Bug reps.', 'On the breathing portion, exhale fully and let the ribs drop down, not flare up; on the Dead Bug portion, keep that same rib and low-back position as you move the limbs.', 'Core', 'mobility', 'per_side'),
  ('Ab/Core: Dead Bug with Light DB', 'Dead Bug performed holding a light dumbbell in the extended hand -- adds a small load challenge to the standard anti-extension pattern.', 'Press the low back flat into the floor and keep it there the whole set; lower the arm/leg only as far as that contact holds.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Overhead Carry + KB Swings 3x10', 'A combo set: an overhead carry for distance/time followed by 10 kettlebell swings, repeated -- pairs a loaded core/shoulder stability challenge with a hip-hinge power movement.', 'On the carry, keep the ribs stacked over the hips and don''t let the loaded arm''s shoulder shrug up; on the swings, drive the hips explosively rather than squatting the weight up.', 'Core', 'compound', 'per_side'),
  ('Ab/Core: Pallof Press + 90/90 Breathing', 'Pallof Press (an anti-rotation press against a band or cable) paired with 90/90 positional breathing to reset core control between sets.', 'On the press, resist any twist toward the resistance -- the whole point is the trunk staying still; on the breathing, exhale fully and let the ribs settle down.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Pallof Press + Bird Dog with Reach', 'Pallof Press paired with a Bird Dog that adds a forward reach at the top of the extension -- combines anti-rotation pressing with anti-rotation reaching.', 'On the press, resist any twist toward the band; on the Bird Dog, keep the hips level and only reach as far as you can without the low back moving.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Seated Marching + Bird Dog', 'A combo set: seated marches (lifting alternating knees from a tall seated position) paired with Bird Dogs -- builds core control in both a seated and a hands-and-knees position.', 'On the march, keep the torso tall and still as each knee lifts; on the Bird Dog, keep the hips level and move slow and controlled.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Seated Trunk Rotation + Bird Dog', 'A combo set: controlled seated trunk rotations paired with Bird Dogs -- rotational core control paired with anti-rotation control.', 'Rotate from the trunk, not by yanking with the arms; keep the hips still on the rotation; on the Bird Dog, keep the hips level and move slow.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Standing Marching + Trunk Rotation (standing)', 'A combo set performed standing: high-knee marches paired with controlled trunk rotations -- builds core control and balance in an upright, functional position.', 'Keep the standing leg stable and the hips level through the march; rotate from the trunk on the rotation portion, not by swinging the arms.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Suitcase Carry (heavier)', 'A heavier-load Suitcase Carry -- walk holding a weight in one hand at your side, resisting the urge to lean away from the load.', 'Stay tall and resist leaning toward or away from the loaded side; take controlled steps, not a rush; switch sides to balance the work.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Suitcase Carry + Pallof Press', 'A combo set: a Suitcase Carry (one-sided loaded walk) paired with Pallof Presses -- both challenge the core''s anti-lateral-flexion and anti-rotation control from different angles.', 'On the carry, stay tall and resist leaning toward the load; on the press, resist any twist toward the band.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Supine 90/90 Breathing', 'Lying on your back with hips and knees stacked at 90 degrees, focusing purely on full diaphragmatic exhales to reset core and rib position.', 'Exhale fully and let the ribs drop down flat, not flare up; keep the low back gently in contact with the floor; there''s no rush -- slow, complete breaths.', 'Core', 'mobility', 'bilateral'),
  ('Ab/Core: Walking Lunge -- laps down & back', 'Walking lunges performed continuously down a set distance and back, rather than in place -- builds single-leg strength alongside a core/balance carryover from the walking pattern.', 'Keep the torso tall through each step; let the back knee drop toward the floor without slamming it down; push through the front leg to bring the trailing leg through to the next step.', 'Quads', 'compound', 'per_leg'),
  ('Ankle Pumps + Circles', 'Simple ankle mobility: pointing/flexing the foot (pumps) and moving it through full circles -- low-intensity work to keep the ankle joint mobile.', 'Move through the full available range without forcing it; keep the movement slow and controlled in both directions on the circles.', 'Calves', 'mobility', 'per_leg'),
  ('Cat-Cow (spinal mobility)', 'From hands and knees, alternating between arching and rounding the spine -- a classic warm-up movement for spinal mobility.', 'Lead with the breath: inhale into the arch (cow), exhale into the round (cat); move through the whole spine, not just the low back.', 'Back', 'mobility', 'bilateral'),
  ('Cat-Cow + Multi-Plane Mobility', 'Cat-Cow combined with additional rotational/side-bending movement through the spine -- expands the basic front-to-back mobility into multiple planes.', 'Move slowly and let each plane of motion come from a different part of the spine; don''t force range that feels blocked -- work around it gently.', 'Back', 'mobility', 'bilateral'),
  ('Cat-Cow + Thoracic Rotation', 'Cat-Cow paired with a rotational reach through the upper back (thoracic spine) -- adds a rotational mobility component to the basic flexion/extension flow.', 'Keep the hips relatively still on the rotation so the movement comes from the upper back, not the low back; move with the breath.', 'Back', 'mobility', 'per_side'),
  ('Cat-Cow / Segmental Spine Mobility', 'Cat-Cow performed with attention to moving through the spine one segment at a time, rather than as one block -- builds finer control through the whole spine.', 'Go slow enough to feel each vertebra move in sequence; lead with the breath; don''t rush to the end range.', 'Back', 'mobility', 'bilateral'),
  ('Cat-Cow w/ Reach', 'Cat-Cow with an added reach of one arm forward or up at the top of the movement -- adds a shoulder/thoracic mobility component to the base flow.', 'Keep the reach controlled and connected to the breath; don''t let the low back overarch to get more reach.', 'Back', 'mobility', 'per_side'),
  ('Child''s Pose w/ Reach', 'A resting stretch position -- hips back toward the heels, arms reaching forward -- that lengthens the low back, hips, and shoulders together.', 'Let the hips settle back and down without forcing it; breathe into the stretch rather than holding tension; reach the arms only as far as feels good.', 'Back', 'mobility', 'bilateral'),
  ('Doorway Chest Stretch', 'A classic chest-opening stretch -- forearm braced on a doorway, stepping through to stretch the front of the shoulder and chest.', 'Keep the elbow roughly shoulder height; step through slowly until a comfortable stretch is felt, not pain; keep the torso upright, not twisted.', 'Chest', 'mobility', 'per_side'),
  ('Doorway Chest Stretch (deeper)', 'The Doorway Chest Stretch taken to a deeper range -- a longer step through or a longer hold to increase the stretch on the chest and front shoulder.', 'Ease into the deeper range rather than forcing it in one step; keep breathing through the hold; back off if it becomes sharp rather than a stretch.', 'Chest', 'mobility', 'per_side'),
  ('Doorway Chest Stretch + Overhead Reach', 'The Doorway Chest Stretch combined with an overhead reach of the free arm -- adds a lat/shoulder mobility component to the base chest stretch.', 'Keep the braced arm at shoulder height while the free arm reaches up and slightly back; breathe into both stretches together.', 'Chest', 'mobility', 'per_side'),
  ('Doorway Chest Stretch + Rotation', 'The Doorway Chest Stretch combined with a gentle rotation of the torso away from the doorway -- adds a rotational stretch component.', 'Keep the braced forearm steady on the frame as the torso rotates away; ease into the rotation, don''t force it.', 'Chest', 'mobility', 'per_side'),
  ('Foam Roll: Full Lower Body', 'Foam rolling through the major lower-body muscle groups (quads, hamstrings, calves, glutes) in sequence -- a broad self-myofascial release pass before or after training.', 'Roll slowly, pausing on any tender spot for a few breaths rather than rolling straight through it; keep the core engaged so the low back isn''t sagging while rolling.', 'Quads', 'mobility', 'bilateral'),
  ('Foam Roll: Full Posterior Chain', 'Foam rolling through the back of the body -- calves, hamstrings, glutes, and low/mid back -- in sequence.', 'Roll slowly, pausing on tender spots for a few breaths; keep movements controlled, not fast passes back and forth.', 'Hamstrings', 'mobility', 'bilateral'),
  ('Foam Roll: Quads & IT Band', 'Foam rolling the front of the thigh and the IT band (outer thigh) -- common tight spots for lower-body training.', 'Roll slowly and pause on tender spots; on the IT band portion, a lighter touch is often more tolerable -- ease into it.', 'Quads', 'mobility', 'per_leg'),
  ('Foam Roll: Quads / IT Band / Glutes', 'An extended foam-rolling pass covering the quads, IT band, and glutes -- a broader lower-body release sequence.', 'Roll slowly, pausing on tender spots for a few breaths; move to the next area once a spot feels less tender rather than grinding on it.', 'Quads', 'mobility', 'per_leg'),
  ('Foam Roll: Thoracic Spine', 'Foam rolling along the upper/mid back -- helps loosen a stiff thoracic spine, especially useful before pressing or overhead work.', 'Support the head with the hands to protect the neck; roll slowly from mid-back to upper-back, avoiding rolling directly on the low back or neck.', 'Back', 'mobility', 'bilateral'),
  ('Foam Roll: Thoracic Spine & Lats', 'Foam rolling the upper/mid back combined with the lats (sides of the upper back) -- a broader upper-back release pass.', 'Support the head with the hands on the thoracic portion; for the lats, roll along the side of the ribs slowly, avoiding directly on the shoulder joint.', 'Back', 'mobility', 'per_side'),
  ('Foam Roll: Thoracic Spine & Shoulders', 'Foam rolling the upper/mid back combined with light rolling around the shoulder blades -- targets common tightness before overhead work.', 'Support the head on the thoracic portion; keep the shoulder-area rolling gentle and avoid rolling directly over the shoulder joint itself.', 'Back', 'mobility', 'bilateral'),
  ('Foam Roll: Upper Back & Lats', 'Foam rolling the upper back combined with the lats -- targets a common tight spot that limits shoulder and overhead mobility.', 'Support the head with the hands on the upper-back portion; roll the lats along the side of the ribs slowly, easing into any tender spots.', 'Back', 'mobility', 'per_side'),
  ('Kneeling Hip Flexor Stretch (PNF)', 'A kneeling hip flexor stretch using a PNF (contract-relax) technique -- gently contracting the stretched muscle briefly before relaxing into a deeper stretch.', 'Hold the stretch position, contract the front hip gently into the floor for a few seconds, then relax and ease slightly deeper; repeat rather than forcing one long push.', 'Balance/Mobility', 'mobility', 'per_leg'),
  ('Kneeling Hip Flexor Stretch (assisted)', 'A kneeling hip flexor stretch with support (a wall, chair, or coach-assisted hold) to help maintain balance and posture through the stretch.', 'Keep the torso tall rather than leaning forward to force the stretch; tuck the hips slightly under for a cleaner stretch through the front of the hip.', 'Balance/Mobility', 'mobility', 'per_leg'),
  ('Kneeling Hip Flexor Stretch + Rotation', 'The kneeling hip flexor stretch with an added gentle torso rotation toward the front leg -- adds a rotational component to the base hip-opening stretch.', 'Keep the hips square and tucked slightly under before adding the rotation; rotate from the torso, not by shifting the hips out of position.', 'Balance/Mobility', 'mobility', 'per_leg'),
  ('Standing Calf Stretch', 'A standing stretch for the calf -- back leg straight, heel down, leaning into a wall or support -- targets the larger calf muscle (gastrocnemius).', 'Keep the back heel flat on the floor and the back leg straight; lean forward from the ankle, not by rounding the back; ease into it, don''t bounce.', 'Calves', 'mobility', 'per_leg'),
  ('Standing Calf Stretch + Ankle Mobility', 'The Standing Calf Stretch combined with active ankle circles or rocks -- pairs a static calf stretch with some active ankle mobility work.', 'Hold the calf stretch with the back heel down; move through the ankle mobility portion slowly and through a full comfortable range.', 'Calves', 'mobility', 'per_leg'),
  ('Standing Calf Stretch + Balance Reach', 'The Standing Calf Stretch combined with a balance reach on the front leg -- adds a stability challenge to the basic calf stretch.', 'Keep the back heel down through the stretch; on the reach, move slowly and only as far as balance allows without wobbling badly.', 'Calves', 'mobility', 'per_leg'),
  ('Standing Calf Stretch w/ Wall', 'The Standing Calf Stretch performed with a wall for support and to control the angle of lean.', 'Keep the back heel flat and the back leg straight; lean into the wall from the ankle, easing in rather than bouncing.', 'Calves', 'mobility', 'per_leg'),
  ('Supine Figure-4 + Full-Body Stretch Flow', 'The Figure-4 hip/glute stretch (lying on the back, ankle crossed over the opposite knee) extended into a broader flow that includes a few other gentle full-body stretches.', 'Ease into each position rather than forcing range; breathe through each hold; keep the movements between positions slow and controlled.', 'Glutes', 'mobility', 'per_leg'),
  ('Supine Figure-4 + Hamstring Stretch', 'The Figure-4 hip/glute stretch paired with a hamstring stretch (straightening and gently pulling the leg toward the chest) -- combines a glute and hamstring stretch in one sequence.', 'Ease into the Figure-4 position first, then transition into the hamstring pull without yanking; keep the head and shoulders relaxed on the floor.', 'Glutes', 'mobility', 'per_leg'),
  ('Supine Figure-4 Stretch', 'Lying on the back, crossing one ankle over the opposite knee and gently pulling the far thigh toward the chest -- a classic hip/glute stretch.', 'Keep the crossed ankle relaxed, not flexed hard against the knee; pull gently from behind the thigh, easing deeper rather than yanking.', 'Glutes', 'mobility', 'per_leg'),
  ('Supine Figure-4 Stretch (deeper)', 'The Supine Figure-4 Stretch taken to a deeper range -- pulling the thigh closer to the chest for more stretch through the hip/glute.', 'Ease into the deeper range gradually rather than forcing it; keep breathing through the hold; back off if it becomes sharp rather than a stretch.', 'Glutes', 'mobility', 'per_leg'),
  ('Thoracic Rotation (seated or standing)', 'A rotational mobility drill for the upper back -- rotating the torso from a seated or standing position while keeping the hips relatively still.', 'Keep the hips facing forward so the rotation comes from the upper back; move slowly through a comfortable range, not forced.', 'Back', 'mobility', 'per_side'),
  ('Thread the Needle + Reach', 'The Thread the Needle stretch (threading one arm under the body from hands and knees) with an added reach in the opposite direction at the top -- adds a rotational range extension.', 'Let the rotation come from the upper back; keep the hips fairly still; move slowly between the threaded and reached positions.', 'Back', 'mobility', 'per_side'),
  ('Thread the Needle Stretch', 'From hands and knees, threading one arm underneath the body and through to the opposite side -- a rotational stretch for the upper back and shoulder.', 'Let the rotation come from the upper back and shoulder, not by collapsing the supporting arm; move slowly into the stretch.', 'Back', 'mobility', 'per_side'),
  ('Ball Flye', 'Lying on a stability ball, a chest fly (arms open wide then come together over the chest) -- the ball adds a light core-stability demand on top of the chest work.', 'Keep a slight bend in the elbows throughout; lower only as far as a comfortable stretch across the chest; keep the hips lifted and stable on the ball.', 'Chest', 'accessory', 'bilateral'),
  ('Ball Flye (heavier)', 'The Ball Flye with a heavier dumbbell load -- same movement, more resistance across the chest.', 'Keep the same controlled range as the lighter version -- don''t let the added weight shorten the range or destabilize the hips on the ball.', 'Chest', 'accessory', 'bilateral'),
  ('Ball Leg Curl', 'Lying on the back with heels on a stability ball, curling the ball in toward the glutes by bending the knees -- targets the hamstrings with a stability demand.', 'Keep the hips lifted throughout, not sagging toward the floor; curl the ball in with control and extend back out just as slowly.', 'Hamstrings', 'accessory', 'bilateral'),
  ('Bench Press (moderate load)', 'A standard barbell or dumbbell Bench Press at a moderate, controlled load -- a foundational chest-pressing movement.', 'Set the shoulder blades back and down before unracking; lower under control to the chest; drive up evenly through both sides.', 'Chest', 'compound', 'bilateral'),
  ('Bicep Curl (light DB)', 'A standard dumbbell Bicep Curl using a light load -- an isolation movement for the front of the upper arm.', 'Keep the elbows pinned at the sides through the whole rep; curl with control, no swinging the torso to help the weight up.', 'Biceps', 'accessory', 'bilateral'),
  ('Bicep Curl (machine/cable)', 'A Bicep Curl performed on a machine or cable station -- isolates the biceps with a guided, consistent resistance path.', 'Keep the elbows in the pads/at the sides; curl with control through the full range; don''t let the weight stack slam down between reps.', 'Biceps', 'accessory', 'bilateral'),
  ('Bicep Curl, heavier DB', 'A dumbbell Bicep Curl using a heavier load than the standard version -- same isolation movement, more resistance.', 'Keep the same strict form as the lighter version -- elbows pinned, no torso swing to muscle the weight up.', 'Biceps', 'accessory', 'bilateral'),
  ('Cable Fly (machine)', 'A chest Fly performed on a cable machine -- arms sweep from wide to together in front of the chest, targeting the chest through a long range of motion.', 'Keep a slight bend in the elbows throughout; control the weight back out to a comfortable stretch rather than letting it yank the arms back.', 'Chest', 'accessory', 'bilateral'),
  ('Chest Press (machine)', 'A Chest Press performed on a seated machine -- a guided, stable version of a chest press movement.', 'Set the seat height so the handles line up with the mid-chest; press through a full range without locking the elbows hard at the top; control the return.', 'Chest', 'compound', 'bilateral'),
  ('DB Bicep Curl', 'A standard dumbbell Bicep Curl -- an isolation movement for the front of the upper arm.', 'Keep the elbows pinned at the sides through the whole rep; curl with control, no swinging the torso to help the weight up.', 'Biceps', 'accessory', 'bilateral'),
  ('DB Bicep Curl (heavier)', 'A dumbbell Bicep Curl using a heavier load -- same isolation movement, more resistance.', 'Keep the same strict form as a lighter curl -- elbows pinned, controlled tempo, no torso swing.', 'Biceps', 'accessory', 'bilateral'),
  ('DB Chest Press', 'A dumbbell Chest Press performed lying on a bench or floor -- a foundational chest-pressing movement that also demands some shoulder stability from the free weights.', 'Set the shoulder blades back and down before pressing; lower under control to chest level; press up evenly through both arms.', 'Chest', 'compound', 'bilateral'),
  ('DB Fly', 'A dumbbell chest Fly -- arms open wide then come together over the chest, targeting the chest through a long stretch-focused range.', 'Keep a slight bend in the elbows throughout; lower only as far as a comfortable stretch across the chest, not to the point of shoulder strain.', 'Chest', 'accessory', 'bilateral'),
  ('DB Overhead Tricep Extension', 'A dumbbell Overhead Tricep Extension -- the weight is lowered behind the head and pressed back up, isolating the triceps.', 'Keep the elbows pointed forward and relatively still, not flaring out; lower under control behind the head; avoid arching the low back to get more range.', 'Triceps', 'accessory', 'bilateral'),
  ('DB Row', 'A dumbbell Row -- hinged over, pulling the weight to the torso -- a foundational back-strengthening movement.', 'Hinge with a flat back roughly parallel to the floor; row by driving the elbow back, not just curling the weight up; lower under control.', 'Back', 'compound', 'bilateral'),
  ('DB Shoulder Press', 'A dumbbell Shoulder Press -- pressing the weights overhead from shoulder height -- a foundational shoulder-strengthening movement.', 'Brace the core so the low back doesn''t overarch as the weight goes overhead; press up and slightly in, finishing with the arms extended over the head, not out in front.', 'Shoulders', 'compound', 'bilateral'),
  ('Face Pull (cable)', 'A Face Pull performed on a cable station -- pulling the rope toward the face with the elbows flared high, targeting the rear shoulders and upper back.', 'Pull toward the face, not the chest; keep the elbows high, roughly in line with the shoulders; squeeze the shoulder blades together at the end of the pull.', 'Shoulders', 'accessory', 'bilateral'),
  ('Face Pull (heavier band)', 'A Face Pull performed with a heavier resistance band -- same rear-shoulder and upper-back movement, more resistance.', 'Keep the same form as a lighter band -- pull toward the face, elbows high, squeeze the shoulder blades at the end.', 'Shoulders', 'accessory', 'bilateral'),
  ('Glute Kickback (machine)', 'A Glute Kickback performed on a machine -- extending one leg back against resistance to isolate the glute.', 'Keep the movement coming from the hip, not the low back arching to add range; squeeze the glute hard at the top of the kick; control the return.', 'Glutes', 'accessory', 'per_leg'),
  ('Hip Abduction (machine)', 'A Hip Abduction performed on a machine -- pressing the legs outward against resistance to target the outer hip/glute (abductors).', 'Keep the torso still and upright; press out with control rather than using momentum; control the return back in.', 'Abductors', 'accessory', 'bilateral'),
  ('Incline DB/Barbell Press', 'An Incline Chest Press performed with dumbbells or a barbell on an inclined bench -- shifts more emphasis to the upper chest and front shoulder compared to a flat press.', 'Set the bench at a moderate incline, not too steep; lower under control to the upper chest; press up evenly through both arms.', 'Chest', 'compound', 'bilateral'),
  ('Lat Pulldown (machine)', 'A Lat Pulldown performed on a cable machine -- pulling a bar down toward the chest from overhead, targeting the lats and upper back.', 'Lead with the elbows down and back, not by yanking with the arms; pull to roughly the collarbone; control the weight back up to a full stretch.', 'Back', 'compound', 'bilateral'),
  ('Lateral Raise (machine or light DB)', 'A Lateral Raise performed on a machine or with light dumbbells -- raising the arms out to the sides to shoulder height, isolating the side shoulder.', 'Lead with the elbows, not the hands; raise to roughly shoulder height, not higher; control the weight back down rather than dropping it.', 'Shoulders', 'accessory', 'bilateral'),
  ('Leg Curl (machine)', 'A Leg Curl performed on a machine -- curling the heels toward the glutes against resistance, isolating the hamstrings.', 'Keep the hips pressed into the pad throughout, not lifting to help the weight; curl with control and extend back out just as slowly.', 'Hamstrings', 'accessory', 'bilateral'),
  ('Leg Extension (machine)', 'A Leg Extension performed on a machine -- extending the knees against resistance from a seated position, isolating the quads.', 'Keep the back against the pad and avoid using momentum; extend through a full comfortable range; lower under control, don''t let the stack drop.', 'Quads', 'accessory', 'bilateral'),
  ('Leg Press (machine)', 'A Leg Press performed on a machine -- pressing a weighted platform away with the legs from a seated/reclined position, a lower-body strength movement.', 'Keep the low back flat against the pad, not rounding as the knees come toward the chest; press through the whole foot; don''t lock the knees out hard at the top.', 'Quads', 'compound', 'bilateral'),
  ('Med Ball Chest Pass', 'Explosively passing a medicine ball out from the chest -- a power-focused chest movement, often done against a wall or with a partner.', 'Load through the chest and arms briefly before an explosive push; follow through fully with the arms; reset your stance between reps.', 'Chest', 'compound', 'bilateral'),
  ('Med Ball Rotational Throw', 'Explosively throwing a medicine ball across the body in a rotational pattern -- builds rotational power through the core and hips.', 'Generate the power from the hips and trunk rotating, not just the arms; follow through fully; reset your stance square between reps.', 'Core', 'compound', 'per_side'),
  ('Overhead Med Ball Throw', 'Explosively throwing a medicine ball overhead and forward (or against a wall) -- a full-body power movement.', 'Load through the hips and core before the throw, not just the arms; follow through and let the whole body extend; reset between reps.', 'Full Body', 'compound', 'bilateral'),
  ('Overhead Press', 'A standard barbell or dumbbell Overhead Press -- pressing the weight from shoulder height straight overhead, a foundational shoulder-strengthening movement.', 'Brace the core so the low back doesn''t overarch as the weight goes overhead; press up and slightly back, finishing directly over the head.', 'Shoulders', 'compound', 'bilateral'),
  ('Overhead Press (moderate load)', 'The Overhead Press at a moderate, controlled load -- same foundational shoulder-pressing movement.', 'Brace the core before pressing; press up and slightly back, finishing directly over the head; control the weight back down.', 'Shoulders', 'compound', 'bilateral'),
  ('Overhead Press, seated, light DB', 'An Overhead Press performed seated with light dumbbells -- removes the legs from the movement to isolate the shoulders and reduce the stability demand.', 'Keep the back supported and the core braced; press up evenly through both arms, finishing overhead rather than out in front.', 'Shoulders', 'compound', 'bilateral'),
  ('Rear Delt Fly (machine)', 'A Rear Delt Fly performed on a machine -- arms sweep backward against resistance, targeting the rear shoulder and upper back.', 'Lead with the elbows, squeezing the shoulder blades together at the back of the movement; control the return, don''t let the weight yank the arms forward.', 'Shoulders', 'accessory', 'bilateral'),
  ('Seated Cable Row', 'A Seated Row performed on a cable machine -- pulling the handle toward the torso from a seated position, a foundational back-strengthening movement.', 'Sit tall and avoid rocking the torso to help the pull; drive the elbows back and squeeze the shoulder blades together; control the return to a full stretch.', 'Back', 'compound', 'bilateral'),
  ('Seated Overhead Press', 'An Overhead Press performed from a seated position -- removes the legs from the movement to isolate the shoulders.', 'Keep the back supported and the core braced; press up evenly, finishing directly overhead rather than out in front.', 'Shoulders', 'compound', 'bilateral'),
  ('Seated Row (band)', 'A Seated Row performed with a resistance band anchored in front of you -- a portable, scalable version of the classic back row.', 'Sit tall, avoid rocking the torso to help the pull; drive the elbows back and squeeze the shoulder blades together; control the band back out.', 'Back', 'compound', 'bilateral'),
  ('Seated Row (machine)', 'A Seated Row performed on a machine -- pulling the handles toward the torso from a seated position, a foundational back-strengthening movement.', 'Sit tall, chest against the pad if there is one; drive the elbows back and squeeze the shoulder blades together; control the return.', 'Back', 'compound', 'bilateral'),
  ('Seated Row (moderate load)', 'A Seated Row at a moderate, controlled load -- same foundational back-strengthening movement, whichever equipment is set up.', 'Sit tall and avoid rocking the torso to help the pull; drive the elbows back and squeeze the shoulder blades together.', 'Back', 'compound', 'bilateral'),
  ('Seated Row, heavier band', 'The band Seated Row using a heavier resistance band -- same movement, more resistance.', 'Keep the same seated, controlled form as a lighter band -- drive the elbows back, squeeze the shoulder blades, control the return.', 'Back', 'compound', 'bilateral'),
  ('Shoulder Press (machine)', 'A Shoulder Press performed on a seated machine -- a guided, stable version of an overhead press.', 'Set the seat height so the handles start roughly at shoulder height; press up through a full range without locking the elbows hard; control the return.', 'Shoulders', 'compound', 'bilateral'),
  ('Single-Arm DB Row', 'A dumbbell Row performed one arm at a time, typically with the other hand/knee braced on a bench -- isolates one side of the back and adds a light core-stability demand.', 'Keep the torso still, not rotating to help the pull; drive the elbow back and up, not just curling the weight; control the lower.', 'Back', 'accessory', 'per_arm'),
  ('Single-Arm Row', 'A Row performed one arm at a time -- isolates one side of the back and adds an anti-rotation core demand from the offset load.', 'Keep the torso square and resist rotating toward the working side; drive the elbow back; control the lower through a full stretch.', 'Back', 'accessory', 'per_arm'),
  ('Single-Arm Row (heavier)', 'The Single-Arm Row with a heavier load -- same movement, more resistance and a bigger anti-rotation demand.', 'Keep the same strict, anti-rotation form as a lighter load -- torso square, controlled tempo, no yanking the weight up with momentum.', 'Back', 'accessory', 'per_arm'),
  ('Single-Arm Wall Slide', 'A Wall Slide performed one arm at a time -- sliding the arm up and down a wall while keeping contact, targeting shoulder blade control and mobility on one side.', 'Keep the arm, wrist, and hand in contact with the wall throughout; move slowly and stop if contact breaks rather than forcing more range.', 'Shoulders', 'mobility', 'per_arm'),
  ('Single-Leg Bicep Curl', 'A standard Bicep Curl performed while balancing on one leg -- adds a balance/stability challenge to the basic arm isolation movement.', 'Keep the standing leg soft, not locked; curl with strict form -- elbow pinned, no torso swing; switch legs to balance the work.', 'Biceps', 'accessory', 'per_leg'),
  ('Standing Push with Band', 'A standing chest/shoulder press performed against a resistance band anchored behind you -- a portable pressing movement.', 'Brace the core and avoid leaning back to help the push; press fully through the arms; control the band back to the chest.', 'Chest', 'compound', 'bilateral'),
  ('Standing Row to Overhead Carry', 'A standing Row transitioning into carrying the load overhead -- pairs a pulling movement with an overhead loaded carry for shoulder stability.', 'On the row, drive the elbows back and squeeze the shoulder blades; on the carry, keep the ribs stacked over the hips and the loaded arm steady overhead.', 'Back', 'compound', 'per_arm'),
  ('Standing Row to Overhead Reach', 'A standing Row transitioning into an overhead reach -- pairs a pulling movement with a reaching/mobility movement.', 'On the row, drive the elbows back; on the reach, keep the ribs stacked over the hips rather than arching the low back to reach higher.', 'Back', 'compound', 'per_arm'),
  ('Standing Row to Overhead Reach (light DB)', 'The Standing Row to Overhead Reach performed holding a light dumbbell -- adds a small load to the combined row-and-reach pattern.', 'Keep the same controlled form as the unloaded version -- drive the elbows back on the row, avoid overarching the low back on the reach.', 'Back', 'compound', 'per_arm'),
  ('Standing Row to Overhead Reach (moderate DB)', 'The Standing Row to Overhead Reach performed holding a moderate dumbbell -- more load on the same combined row-and-reach pattern.', 'Keep the same controlled form as the lighter version -- drive the elbows back on the row, avoid overarching the low back on the reach.', 'Back', 'compound', 'per_arm'),
  ('Standing Row, balance challenge', 'A standing Row performed with an added balance challenge (e.g. single-leg stance, unstable surface) -- combines back strengthening with balance training.', 'Keep the standing base stable before adding speed or load; drive the elbows back and squeeze the shoulder blades on the row itself.', 'Back', 'compound', 'per_leg'),
  ('Tricep Pushdown (cable/machine)', 'A Tricep Pushdown performed on a cable or machine station -- pressing the handle down against resistance, isolating the triceps.', 'Keep the elbows pinned at the sides through the whole rep; extend fully at the bottom without locking out hard; control the return.', 'Triceps', 'accessory', 'bilateral'),
  ('Wall Slide / Scapular Retraction', 'Sliding both arms up and down a wall while maintaining contact, paired with actively squeezing the shoulder blades together -- builds shoulder blade control and overhead mobility.', 'Keep the arms, wrists, and low back in contact with the wall throughout; move slowly and only as high as contact holds; squeeze the shoulder blades together at the start.', 'Shoulders', 'mobility', 'bilateral'),
  ('Wall Slide w/ Band', 'The Wall Slide performed with a light resistance band around the wrists or hands -- adds a small resistance challenge to the shoulder-control pattern.', 'Keep light tension on the band throughout; keep the arms in contact with the wall; move slowly, don''t let the band yank the arms out of position.', 'Shoulders', 'mobility', 'bilateral'),
  ('Wall Slide w/ Band (higher rep)', 'The banded Wall Slide performed for a higher rep count -- same movement, more volume to build endurance in shoulder blade control.', 'Keep the same controlled quality through every rep, not just the first few; keep light band tension throughout; stop early rather than letting form break down.', 'Shoulders', 'mobility', 'bilateral'),
  ('Back Squat', 'A barbell squat carried across the upper back -- one of the core lower-body strength builders.', 'Set the bar across the traps (or slightly lower for a low-bar variation); brace the core before unracking; sit back and down with the chest tall; drive the floor away evenly through both feet.', 'Quads', 'compound', 'bilateral'),
  ('Bodyweight Squat to Chair', 'A bodyweight squat performed down to a chair or bench, lightly tapping it before standing back up -- teaches consistent squat depth and control without added load.', 'Reach the hips back to find the chair, not just bending the knees; keep the chest tall; tap the chair lightly, don''t sit and rest, then drive back up.', 'Quads', 'compound', 'bilateral'),
  ('Bulgarian Split Squat (loaded)', 'A loaded Bulgarian Split Squat -- rear foot elevated on a bench, holding weight while lowering into a lunge on the front leg.', 'Keep most of the weight on the front leg -- the back foot is for balance, not driving the movement; lower until the front thigh is roughly parallel to the floor; drive through the front foot to stand.', 'Quads', 'compound', 'per_leg'),
  ('Bulgarian Split Squat Jump', 'An explosive version of the Bulgarian Split Squat -- rear foot elevated, driving up into a small jump from the front leg.', 'Master the controlled version before adding the jump; land soft with a slight bend in the front knee; reset your position before the next rep.', 'Quads', 'compound', 'per_leg'),
  ('Curtsy Lunge', 'A lunge that steps one leg diagonally behind and across the body -- targets the glutes (especially glute medius) through a diagonal plane most lunges don''t hit.', 'Step diagonally behind and across, lowering the back knee toward the floor; keep the front knee tracking over the toes; push through the front leg to return to standing.', 'Glutes', 'compound', 'per_leg'),
  ('Front/Goblet Squat (heavier)', 'A heavier-load Front Squat or Goblet Squat -- the load held at the front of the body (rack position or goblet hold), which naturally keeps the torso more upright than a back squat.', 'Keep the chest tall and elbows up (front rack) or the weight close to the chest (goblet); sit straight down between the hips; drive through the whole foot to stand.', 'Quads', 'compound', 'bilateral'),
  ('Glute Bridge (bodyweight, partial range)', 'A bodyweight Glute Bridge performed through a shortened, pain-free range -- lifting the hips only as far as feels completely comfortable.', 'Lift only as far as feels pain-free and controlled; squeeze the glutes at the top of whatever range you reach; lower with control.', 'Glutes', 'accessory', 'bilateral'),
  ('Glute Bridge March', 'Holding a Glute Bridge position at the top while marching the knees up one at a time -- adds a single-leg stability and hip-flexor challenge to the basic bridge.', 'Keep the hips level and still as each knee lifts -- don''t let the hips dip or rotate; keep the glutes squeezed throughout.', 'Glutes', 'accessory', 'per_leg'),
  ('Glute Bridge, slow controlled', 'A basic Glute Bridge performed with a deliberately slow tempo on both the lift and the lower -- emphasizes control over speed or load.', 'Lift through a 2-3 count and lower through the same; squeeze the glutes hard at the top; don''t let the low back do the work by overarching.', 'Glutes', 'accessory', 'bilateral'),
  ('Goblet Squat', 'A squat holding a single weight (dumbbell or kettlebell) at the chest -- the front-loaded position naturally encourages an upright torso and good depth.', 'Hold the weight close to the chest; sit straight down between the knees, keeping the torso tall; drive through the whole foot to stand.', 'Quads', 'compound', 'bilateral'),
  ('Goblet Squat (deepest controlled range)', 'A Goblet Squat performed to the deepest range you can control well -- emphasizes full mobility and control at the bottom rather than load.', 'Go only as deep as you can control without the low back rounding or the heels lifting; pause briefly at the bottom; drive back up through the whole foot.', 'Quads', 'compound', 'bilateral'),
  ('Goblet Squat (higher rep)', 'A Goblet Squat performed for a higher rep count than usual -- same movement, more volume to build muscular endurance.', 'Keep the same quality of depth and torso position on rep 15 as rep 1; don''t let fatigue turn it into a bounce at the bottom.', 'Quads', 'compound', 'bilateral'),
  ('Goblet Squat to Chair (light DB)', 'A Goblet Squat performed down to a chair, holding a light dumbbell at the chest -- combines the chair-assisted squat pattern with a small external load.', 'Reach the hips back to find the chair; keep the weight close to the chest; tap the chair lightly, then drive back up through the whole foot.', 'Quads', 'compound', 'bilateral'),
  ('Goblet Squat to Depth', 'A Goblet Squat performed to full, controlled depth -- no chair or target, going as low as good form allows.', 'Keep the weight close to the chest and the torso tall; go only as deep as you can control without the heels lifting or the low back rounding.', 'Quads', 'compound', 'bilateral'),
  ('Jump Squat', 'An explosive squat that drives up into a jump -- builds lower-body power on top of basic squat strength.', 'Master the controlled squat before adding the jump; land soft with bent knees, absorbing the landing rather than stopping stiff; reset before the next rep.', 'Quads', 'compound', 'bilateral'),
  ('Lateral Step, controlled', 'A controlled step out to the side and back -- builds frontal-plane (side-to-side) hip strength and balance at a slow, deliberate pace.', 'Step out with control, not a fall into the step; keep the knee tracking over the toes; push back through the stepping leg to return to center.', 'Abductors', 'accessory', 'per_leg'),
  ('Lateral Step-Up', 'A Step-Up performed sideways onto a box or step, rather than straight ahead -- targets the outer hip and glute alongside the quad.', 'Step up through the whole foot on the box, not pushing off the trailing leg; keep the working knee tracking over the toes; control the step back down.', 'Glutes', 'compound', 'per_leg'),
  ('Multi-Planar Lunge, controlled', 'A lunge performed in multiple directions (forward, side, diagonal) in a slow, controlled sequence -- builds strength and control through more planes of motion than a standard lunge.', 'Move slowly and stick each position before returning to center; keep the working knee tracking over the toes in every direction; keep the torso tall throughout.', 'Quads', 'compound', 'per_leg'),
  ('Reverse Lunge w/ Lift', 'A Reverse Lunge (stepping backward into the lunge) paired with a knee lift of the trailing leg as you return to standing -- adds a balance and hip-flexor challenge to the base lunge.', 'Step back with control, keeping the front knee over the ankle; drive through the front leg to stand, lifting the back knee up with control rather than momentum.', 'Quads', 'compound', 'per_leg'),
  ('Single-Leg Box Step-Down (deceleration)', 'Stepping down off a box on one leg with a focus on controlling the landing rather than dropping -- builds eccentric (deceleration) strength, important for injury resilience.', 'Lower as slowly as you can control; let the working knee bend to absorb the landing rather than landing stiff-legged; keep the hips level throughout.', 'Quads', 'compound', 'per_leg'),
  ('Skater Hops', 'A lateral bounding movement -- hopping side to side from one leg to the other -- builds lateral power, balance, and deceleration strength.', 'Land soft on the outside leg, absorbing through a bent knee; keep the hips level on landing; only add speed once the landing is controlled.', 'Glutes', 'compound', 'per_leg'),
  ('Split Squat', 'A stationary staggered-stance lower-body exercise -- builds single-leg strength and balance without the stepping motion of a lunge.', 'Take a split stance long enough that the front knee stays over the ankle at the bottom; lower straight down until both knees reach roughly 90 degrees; drive through the front foot to stand.', 'Quads', 'compound', 'per_leg'),
  ('Split Squat (loaded)', 'The Split Squat performed holding added weight -- same stationary staggered-stance movement, more resistance.', 'Keep the same split-stance depth and knee position as the unloaded version; drive through the front foot to stand; keep the torso upright under the added load.', 'Quads', 'compound', 'per_leg'),
  ('Step-Down, controlled', 'Stepping down off a box or step with a deliberately slow, controlled tempo -- builds single-leg strength and control on the lowering (eccentric) portion.', 'Lower as slowly as you can control the whole way; let the working knee track over the toes; keep the hips level, not dropping to one side.', 'Quads', 'compound', 'per_leg'),
  ('Step-Up (moderate ht., DB)', 'A Step-Up onto a moderate-height box, holding dumbbells -- a loaded single-leg strength movement.', 'Step up through the whole foot on the box, not pushing off the trailing leg; keep the working knee tracking over the toes; control the step back down.', 'Quads', 'compound', 'per_leg'),
  ('Step-Up w/ Lift', 'A Step-Up onto a box that adds a knee lift of the trailing leg at the top -- combines single-leg strength with a hip-flexor and balance challenge.', 'Step up through the whole foot, not pushing off the trailing leg; once standing tall on the box, lift the trailing knee with control; step back down slowly.', 'Quads', 'compound', 'per_leg'),
  ('Step-Up w/ Lift (loaded)', 'The Step-Up w/ Lift performed holding added weight -- same combined step-up-and-knee-lift movement, more resistance.', 'Keep the same controlled step and knee lift as the unloaded version; don''t let the added load turn the step into a push off the back leg.', 'Quads', 'compound', 'per_leg'),
  ('Step-Up, real stair height', 'A Step-Up performed at a real stair-step height rather than a taller box -- a functional-carryover version of the step-up pattern.', 'Step up through the whole foot, not pushing off the trailing leg; keep the working knee tracking over the toes; control the step back down.', 'Quads', 'compound', 'per_leg'),
  ('Sumo Squat / Front Squat', 'Either a wide-stance Sumo Squat or a Front Squat, both of which keep the torso more upright than a standard back squat -- targets the quads and inner thighs with an upright torso.', 'On the sumo version, keep the knees pushed out in line with the toes; on the front version, keep the elbows up and chest tall; sit straight down through either.', 'Quads', 'compound', 'bilateral'),
  ('Walking Lunge (loaded)', 'A Walking Lunge performed holding added weight -- stepping forward into a lunge, then continuing forward into the next step rather than returning to start.', 'Keep the torso tall through each step; let the back knee drop toward the floor without slamming it; push through the front leg to bring the trailing leg into the next step.', 'Quads', 'compound', 'per_leg'),
  ('Walking Lunge (loaded, controlled)', 'The loaded Walking Lunge performed at a deliberately slower, more controlled tempo -- emphasizes control over speed through the same forward-stepping pattern.', 'Slow the whole movement down -- the step, the lower, and the drive back up; keep the torso tall throughout; don''t let momentum carry you into the next step.', 'Quads', 'compound', 'per_leg'),
  ('Box Jump', 'Jumping explosively from the ground onto a raised box -- a classic lower-body power movement.', 'Swing the arms to help generate power; land softly with bent knees on top of the box, don''t just clear the edge; step back down rather than jumping down.', 'Glutes', 'compound', 'bilateral'),
  ('Broad Jump', 'Jumping explosively forward for distance -- a horizontal-power version of the vertical jump, builds lower-body power in a different plane.', 'Load the hips back before jumping, swing the arms forward to help; land soft with bent knees, absorbing the landing under control.', 'Glutes', 'compound', 'bilateral'),
  ('Farmer''s Carry', 'Walking while holding a heavy weight in each hand -- a foundational full-body strength and grip movement.', 'Stand tall with the shoulders back, not hunched forward by the weight; take controlled steps; keep the core braced throughout.', 'Full Body', 'compound', 'bilateral'),
  ('Heel Raise, light resistance', 'A standing Calf Raise performed with a light added resistance (band or light weight) -- builds on a bodyweight calf raise with a bit more load.', 'Rise all the way onto the toes, pause briefly at the top; lower under control rather than dropping; keep the movement smooth, not bouncy.', 'Calves', 'accessory', 'bilateral'),
  ('Hip Thrust (explosive up)', 'A Hip Thrust performed with an explosive drive on the way up (while still controlling the lower) -- adds a power component to the standard glute-focused hip extension.', 'Drive up explosively through the heels while keeping the movement controlled, not sloppy; squeeze the glutes hard at the top; lower with control before the next rep.', 'Glutes', 'compound', 'bilateral'),
  ('Hip Thrust (heaviest controlled load)', 'A Hip Thrust performed at the heaviest load that can still be moved with full control and a clean lockout -- the top end of controlled-tempo hip thrust progression.', 'Keep the same full range and controlled tempo as lighter loads -- don''t let the heavier weight shorten the range or cause the low back to take over; squeeze the glutes hard at the top.', 'Glutes', 'compound', 'bilateral'),
  ('Hip Thrust (heaviest load)', 'A Hip Thrust performed at the heaviest load in the progression -- the top end of the loaded hip thrust ladder.', 'Keep the same full range as lighter loads -- don''t let the heavier weight shorten the range; squeeze the glutes hard at the top and control the lower.', 'Glutes', 'compound', 'bilateral'),
  ('Hip Thrust (higher volume)', 'A Hip Thrust performed for a higher rep count than usual -- same movement, more volume to build muscular endurance in the glutes.', 'Keep the same quality of lockout and glute squeeze on the last rep as the first; don''t let fatigue turn it into a partial-range bounce.', 'Glutes', 'compound', 'bilateral'),
  ('Hollow Hold', 'An isometric core hold -- lying on the back, lower back pressed to the floor, arms and legs extended and lifted slightly -- builds anti-extension core strength and endurance.', 'Press the low back flat into the floor and keep it there for the whole hold; lower the arms/legs only as far as that contact holds; breathe through the hold rather than holding your breath.', 'Core', 'accessory', 'bilateral'),
  ('Isometric Wall Sit (short hold, pain-free range)', 'A Wall Sit held for a short duration, kept inside a pain-free range -- back against the wall, knees bent to whatever angle feels comfortable, held statically.', 'Only sit down to a depth that feels completely pain-free; keep the back flat against the wall; breathe normally through the hold rather than holding your breath.', 'Quads', 'accessory', 'bilateral'),
  ('Jump Push-Up / Explosive Press', 'An explosive push-up (or press) that drives the hands off the ground (or the weight off the chest explosively) -- builds upper-body power.', 'Master the controlled version of the movement first; land soft on the hands if performing the jump version; keep the core braced throughout.', 'Chest', 'compound', 'bilateral'),
  ('Lateral Bound', 'Bounding explosively from one leg to the other side to side -- similar to Skater Hops, builds lateral power and single-leg landing control.', 'Land soft on the outside leg with a bent knee, absorbing the landing; keep the hips level on landing; only add speed once landings are controlled.', 'Glutes', 'compound', 'per_leg'),
  ('Marching in Place, faster tempo', 'Marching in place at a quicker pace than a basic march -- adds a light cardiovascular and coordination challenge to the basic balance movement.', 'Keep the torso tall and the core braced as the tempo increases; if balance starts to break down, slow back down rather than pushing through poor form.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Marching in Place, holding counter', 'Marching in place (lifting alternating knees) while holding a counter or stable support -- builds balance and hip-flexor endurance with support available.', 'Use the counter for light support, not to lean heavily on; keep the torso tall as each knee lifts; keep a steady, controlled pace.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Marching with High-Knee Reach', 'Marching in place with a higher knee lift and a reach at the top -- adds range and a small balance challenge to the basic march.', 'Keep the torso tall, not leaning back to help the knee lift higher; control the tempo rather than rushing; keep the standing leg stable.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Overhead Carry', 'Walking while holding weight extended overhead -- builds shoulder stability and core control under a loaded, elevated position.', 'Keep the ribs stacked over the hips, not letting the low back arch to support the overhead load; keep the loaded arm(s) locked in a stable position; take controlled steps.', 'Shoulders', 'compound', 'bilateral'),
  ('Overhead Reach (functional)', 'A simple overhead reaching movement, done in a functional/standing context -- builds shoulder mobility and overhead control useful for daily-life reaching tasks.', 'Reach fully without arching the low back to get more height; keep the core braced; move at a controlled pace.', 'Shoulders', 'mobility', 'bilateral'),
  ('Overhead Reach with Step', 'An overhead reach combined with a step -- pairs a shoulder mobility movement with a balance/coordination challenge from the stepping motion.', 'Keep the reach controlled and avoid arching the low back for more height; step with control, keeping the standing leg stable during the reach.', 'Shoulders', 'mobility', 'per_leg'),
  ('Pull-Up / Row (explosive)', 'An explosive Pull-Up or Row -- pulling with speed and power rather than a slow, controlled tempo -- builds pulling power on top of base back strength.', 'Master the controlled version of the pull before adding speed; pull explosively but control the lowering portion; don''t let the added speed turn into sloppy form.', 'Back', 'compound', 'bilateral'),
  ('Seated Dead Bug (supported)', 'A Dead Bug variation performed from a seated, back-supported position -- an accessible version of the anti-extension core pattern for those who find the floor version difficult.', 'Keep the low back in contact with the support throughout; move the limbs only as far as that contact holds; keep the movement slow and controlled.', 'Core', 'accessory', 'per_side'),
  ('Seated Pallof Press (light)', 'A Pallof Press (anti-rotation press against a band or cable) performed seated with a light resistance -- an accessible version of the standing anti-rotation press.', 'Sit tall and resist any twist toward the resistance -- the trunk staying still is the whole point; press and return with control.', 'Core', 'accessory', 'per_side'),
  ('Side Step-Up w/ Balance', 'A Step-Up performed sideways onto a box, with added attention to balance/control at the top -- targets the outer hip and glute with a stability demand.', 'Step up through the whole foot, keeping the working knee tracking over the toes; pause briefly at the top to challenge balance; control the step back down.', 'Glutes', 'compound', 'per_leg'),
  ('Side-Stepping, added resistance band', 'Side-stepping with a light resistance band around the legs -- adds resistance to the basic lateral stepping/walking pattern.', 'Keep tension on the band throughout, not letting the feet come fully together; keep the knees slightly bent and the torso tall.', 'Abductors', 'accessory', 'per_leg'),
  ('Side-Stepping, hand-rail support', 'Side-stepping while holding a hand rail or other stable support -- builds lateral hip strength and balance with support available.', 'Use the rail for light support, not to lean heavily on; take controlled steps, keeping the knees slightly bent; keep the torso tall.', 'Abductors', 'accessory', 'per_leg'),
  ('Side-Stepping, longer distance', 'Side-stepping continuously over a longer distance than a basic set -- adds volume and a light conditioning element to the lateral stepping pattern.', 'Maintain the same controlled step quality at the end of the distance as at the start; keep the knees slightly bent and the torso tall throughout.', 'Abductors', 'accessory', 'per_leg'),
  ('Single-Leg Balance Reach', 'Balancing on one leg while reaching the free leg or arms in different directions -- builds single-leg balance and hip control.', 'Keep the standing knee soft, not locked; move the reach slowly and only as far as balance allows without wobbling badly; switch legs to balance the work.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Single-Leg Stance with Reach', 'Balancing on one leg while reaching forward, side, or across with the arms -- builds single-leg balance under a shifting center of gravity.', 'Keep the standing knee soft, not locked; reach only as far as balance allows without wobbling badly; switch legs to balance the work.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Single-Leg Stance, holding counter', 'Balancing on one leg while holding a counter or stable support -- a foundational balance exercise with support available.', 'Use the counter for light support, not to lean heavily on; keep the standing knee soft, not locked; hold as steady as possible.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Sit-to-Stand (chair, hands assisted as needed)', 'Standing up from a chair and sitting back down, using the hands on the armrests or seat for assistance as needed -- a foundational functional-strength movement.', 'Lean the torso forward slightly before standing to shift weight over the feet; use as little hand assistance as comfortably possible; lower back down with control, not dropping into the seat.', 'Quads', 'compound', 'bilateral'),
  ('Sit-to-Stand to Short Walk', 'Standing up from a chair and continuing directly into a few steps of walking -- links the sit-to-stand pattern with functional gait.', 'Stand up with control before starting to walk, don''t rush the transition; keep the first few steps deliberate and controlled.', 'Quads', 'compound', 'bilateral'),
  ('Sit-to-Stand to Walk, timed', 'The Sit-to-Stand to Short Walk performed against a clock -- adds a light pacing/urgency element to the same functional pattern.', 'Keep the same quality of stand and walk as the untimed version -- don''t sacrifice control for speed; a slightly slower, clean rep beats a fast sloppy one.', 'Quads', 'compound', 'bilateral'),
  ('Sit-to-Stand, slower tempo', 'The Sit-to-Stand movement performed with a deliberately slow tempo on both standing up and sitting back down -- builds control and strength through the full range.', 'Take a full 2-3 count to stand and the same to sit back down; use as little hand assistance as comfortably possible; keep the movement smooth, not jerky.', 'Quads', 'compound', 'bilateral'),
  ('Standing Ankle Circles + Toe Raises', 'Standing ankle circles paired with toe raises (lifting the front of the foot while the heel stays down) -- builds ankle mobility and the muscles that lift the foot.', 'Move through a full, controlled range on the circles; on the toe raises, lift the whole front of the foot, not just the toes; use light support if balance is a concern.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Standing Ankle Raises', 'Standing ankle/calf raises -- rising onto the toes and lowering back down -- a basic calf and ankle-stability movement.', 'Rise all the way onto the toes, pause briefly, then lower under control; use light support if balance is a concern rather than rushing the reps.', 'Calves', 'accessory', 'bilateral'),
  ('Standing Hip Circles', 'Standing on one leg and circling the other leg through a controlled range at the hip -- builds hip mobility and single-leg balance.', 'Keep the standing leg stable and the torso tall; move the circling leg through a smooth, controlled range in both directions; use light support if needed.', 'Balance/Mobility', 'mobility', 'per_leg'),
  ('Standing Hip Circles, added range', 'The Standing Hip Circles taken through a larger range of motion -- same movement, more hip mobility challenge.', 'Keep the standing leg stable and the torso tall even as the range increases; don''t let the added range come from the torso swaying instead of the hip moving.', 'Balance/Mobility', 'mobility', 'per_leg'),
  ('Standing Hip Hinge, light', 'A basic standing Hip Hinge -- pushing the hips back while keeping a flat back, without added load -- the foundational movement pattern behind deadlifts and RDLs.', 'Push the hips straight back, not squatting down; keep a flat back and a soft bend in the knees; feel a stretch through the hamstrings, then drive the hips forward to stand.', 'Hamstrings', 'compound', 'bilateral'),
  ('Standing Hip Hinge, light DB', 'The Standing Hip Hinge performed holding a light dumbbell -- adds a small external load to the basic hinge pattern.', 'Keep the same flat back and hip-back movement as the unloaded version; keep the weight close to the legs; drive the hips forward to stand.', 'Hamstrings', 'compound', 'bilateral'),
  ('Standing Marching, controlled', 'Standing marches (lifting alternating knees) performed at a deliberately controlled, slower tempo -- emphasizes balance and control over pace.', 'Keep the torso tall and still as each knee lifts; control the tempo rather than rushing; use light support if balance is a concern.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Suitcase Carry', 'Walking while holding a weight in one hand at your side -- challenges the core''s anti-lateral-flexion control (resisting leaning toward the load).', 'Stay tall and resist leaning toward or away from the loaded side; take controlled steps; switch sides to balance the work.', 'Core', 'accessory', 'per_side'),
  ('Toe Raises, balance-focused', 'Standing toe raises (lifting the front of the foot while the heel stays down) performed with extra attention to balance -- builds ankle strength and stability together.', 'Keep the standing base stable, using light support if needed; lift the whole front of the foot, not just the toes; control the lower.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Bird Dog', 'From hands and knees, extending the opposite arm and leg out straight while keeping the back flat and still -- a foundational anti-rotation core exercise.', 'Keep the hips level and the low back still -- imagine a cup of water balanced on it; reach long through the fingertips and heel rather than lifting high; move slow and controlled.', 'Core', 'accessory', 'per_side'),
  ('Bird Dog + Reach', 'Bird Dog with an added forward reach of the extended arm at the top of the movement -- extends the range slightly while keeping the anti-rotation demand.', 'Keep the hips level throughout, even as the reach extends further; only reach as far as you can without the low back moving.', 'Core', 'accessory', 'per_side'),
  ('Bird Dog w/ Band', 'Bird Dog performed with a light resistance band (often around the extended hand and foot, or as external resistance) -- adds a small load to the base pattern.', 'Keep the same controlled tempo and level hips as the unbanded version; don''t let the band pull you out of position.', 'Core', 'accessory', 'per_side'),
  ('Bird Dog, longer hold', 'Bird Dog with an extended hold at the top of the extension -- builds core endurance on top of the base movement.', 'Keep the hips dead level through the whole hold, not just the first second; breathe normally rather than holding your breath through the hold.', 'Core', 'accessory', 'per_side'),
  ('Dead Bug', 'Lying on the back, lowering the opposite arm and leg toward the floor while keeping the low back pressed flat -- a foundational anti-extension core exercise.', 'Press the low back flat into the floor and keep it there the whole set; lower the arm/leg only as far as that contact holds; move slow and controlled.', 'Core', 'accessory', 'per_side'),
  ('Dead Bug w/ Light DB', 'Dead Bug performed holding a light dumbbell in the extended hand -- adds a small load challenge to the base anti-extension pattern.', 'Press the low back flat into the floor and keep it there the whole set; lower the arm/leg only as far as that contact holds.', 'Core', 'accessory', 'per_side'),
  ('Dead Bug w/ Moderate DB', 'Dead Bug performed holding a moderate dumbbell load -- more resistance on the same anti-extension pattern.', 'Keep the same strict low-back-to-floor contact as lighter loads; don''t let the added weight shorten the range or break that contact.', 'Core', 'accessory', 'per_side'),
  ('Single-Leg Dead Bug', 'A Dead Bug variation performed moving only the legs (or only one side at a time) -- isolates the lower-body portion of the anti-extension pattern.', 'Press the low back flat into the floor and keep it there; lower the leg only as far as that contact holds; move slow and controlled.', 'Core', 'accessory', 'per_leg'),
  ('Clamshell', 'Lying on your side, knees bent, opening the top knee like a clamshell while keeping the feet together -- isolates the outer hip/glute (abductors).', 'Keep the hips stacked, not rolling backward to open the knee further; move through a controlled range and squeeze at the top; keep the feet touching throughout.', 'Abductors', 'accessory', 'per_side'),
  ('Banded Clamshell', 'The Clamshell performed with a light resistance band around the thighs -- adds resistance to the basic outer-hip isolation movement.', 'Keep the hips stacked, not rolling backward; keep tension on the band throughout the movement, not just at the top.', 'Abductors', 'accessory', 'per_side'),
  ('Bosu Ball Squat', 'Stand on the flat or dome side of a Bosu ball, feet shoulder-width apart, and perform a standard squat -- hips back and down, chest up -- while managing the extra balance demand of the unstable surface.', 'Move slower than on flat ground and don''t rush the reps; the instability should challenge balance, not cause the knees to cave or the depth to shrink dramatically.', 'Quads', 'compound', 'bilateral'),
  ('Goblet Squat (Bosu Ball)', 'A Goblet Squat (weight held at the chest) performed standing on a Bosu ball -- combines a front-loaded squat with a balance challenge from the unstable surface.', 'Hold the weight close to the chest for a stable center of mass; move slower than on flat ground; keep the torso tall throughout.', 'Quads', 'compound', 'bilateral'),
  ('Banded Glute Bridge', 'A Glute Bridge performed with a light resistance band around the thighs -- adds an outer-hip activation demand on top of the basic hip-extension movement.', 'Press the knees out gently against the band throughout, not just at the top; drive through the heels and squeeze the glutes at the top.', 'Glutes', 'accessory', 'bilateral'),
  ('Banded Glute Bridge (higher rep)', 'The Banded Glute Bridge performed for a higher rep count -- same movement, more volume.', 'Keep the same quality of glute squeeze and knee-out band tension on the last rep as the first; don''t let fatigue shorten the range.', 'Glutes', 'accessory', 'bilateral'),
  ('Banded Lateral Walk + Pulse', 'Side-stepping with a resistance band around the legs, adding a small pulse (mini up-down movement) at intervals -- builds outer-hip endurance beyond a standard band walk.', 'Keep tension on the band throughout, not letting the feet come together; keep a slight knee bend and stay low through the whole set.', 'Abductors', 'accessory', 'per_leg'),
  ('Calf Raise, balance-focused', 'A standing Calf Raise performed with extra attention to balance -- rising onto the toes while keeping the whole body stable and controlled.', 'Rise onto the toes with control, not a bounce; keep the ankles stacked under the hips rather than rolling out; use light support if balance is a concern.', 'Calves', 'accessory', 'bilateral'),
  ('Face Pull', 'Pulling a rope or band toward the face with the elbows flared high -- targets the rear shoulders and upper back, commonly used for shoulder health.', 'Pull toward the face, not the chest; keep the elbows high, roughly in line with the shoulders; squeeze the shoulder blades together at the end of the pull.', 'Shoulders', 'accessory', 'bilateral'),
  ('Glute Bridge (loaded)', 'A Glute Bridge performed with added weight across the hips -- more resistance on the basic hip-extension movement.', 'Drive through the heels to lift the hips until the body forms a straight line from shoulders to knees, squeezing the glutes hard at the top; lower under control.', 'Glutes', 'accessory', 'bilateral'),
  ('Heel-to-Toe Walk (near wall for safety)', 'Walking in a straight line placing the heel of one foot directly in front of the toes of the other -- a classic balance and gait exercise, performed near a wall for safety.', 'Keep the arms out for balance if needed; move slowly and deliberately; use the wall for a light touch if balance wavers, not a constant lean.', 'Balance/Mobility', 'accessory', 'bilateral'),
  ('Heel-to-Toe Walk, added challenge', 'The Heel-to-Toe Walk performed with an added challenge -- longer distance, no wall support, or eyes-forward focus rather than looking at the feet.', 'Keep the same controlled, deliberate steps as the supported version; if balance becomes unsafe, step out and reset rather than stumbling through.', 'Balance/Mobility', 'accessory', 'bilateral'),
  ('Hip Abduction (band/cable)', 'Moving the leg outward against a resistance band or cable, targeting the outer hip and glute (abductors).', 'Keep the torso still and upright, not leaning to help the leg move; press out with control rather than momentum; control the return.', 'Abductors', 'accessory', 'per_leg'),
  ('Hip Hinge Pattern (bodyweight RDL)', 'A bodyweight Romanian Deadlift pattern -- pushing the hips back with a flat back and a soft knee bend, without added load -- teaches the fundamental hip-hinge movement.', 'Push the hips straight back, not squatting down; keep a flat back and reach the hands toward the floor/shins; feel a stretch through the hamstrings before driving the hips forward to stand.', 'Hamstrings', 'compound', 'bilateral'),
  ('Hip Hinge Pattern (light DB RDL)', 'The Hip Hinge Pattern performed holding a light dumbbell -- adds a small external load to the basic RDL pattern.', 'Keep the same flat back and hip-back movement as the bodyweight version; keep the weight close to the legs throughout.', 'Hamstrings', 'compound', 'bilateral'),
  ('Hip Hinge to RDL (moderate DB)', 'The Hip Hinge Pattern performed with a moderate dumbbell load, progressing toward a full Romanian Deadlift -- more resistance on the same fundamental pattern.', 'Keep the same flat back and controlled hip-back movement as lighter loads; feel the stretch through the hamstrings before driving the hips forward.', 'Hamstrings', 'compound', 'bilateral'),
  ('Hip Thrust (heavy)', 'A Hip Thrust performed at a heavy, challenging load -- one of the most direct ways to load and build the glutes.', 'Shoulders supported on a bench, feet planted hip-width apart; drive through the heels to lift the hips until the body forms a straight line from shoulders to knees, squeezing the glutes hard at the top.', 'Glutes', 'compound', 'bilateral'),
  ('Incline Push-Up, more challenge', 'An Incline Push-Up performed at a lower incline (or with feet elevated) than a beginner version -- a harder progression of the hands-elevated push-up.', 'Keep the body in a straight line from head to heels; lower with control to just above the surface; press back up evenly through both arms.', 'Chest', 'compound', 'bilateral'),
  ('Isometric Shoulder External Rotation (band, light)', 'Holding the shoulder in an externally rotated position against light band resistance without moving -- an isometric hold that targets the rotator cuff.', 'Keep the elbow pinned at the side throughout; hold a steady position rather than letting the band pull the arm back in; breathe normally through the hold.', 'Shoulders', 'accessory', 'per_arm'),
  ('Lateral Band Walk', 'Side-stepping with a resistance band around the legs -- targets the outer hip and glute (abductors) through repeated lateral steps.', 'Keep tension on the band throughout, not letting the feet come fully together; keep a slight knee bend and stay low through the whole set.', 'Abductors', 'accessory', 'per_leg'),
  ('Lateral Lunge', 'A lunge that steps directly out to the side rather than forward or back -- targets the inner and outer thigh through a frontal-plane movement most lunges don''t hit.', 'Step out to the side and sit the hips back and down over the working leg; keep the trailing leg straight with the foot flat; push back through the working leg to return to center.', 'Adductors', 'compound', 'per_leg'),
  ('Plyo Push-Up', 'An explosive push-up where the hands leave the ground at the top -- builds upper-body power on top of standard push-up strength.', 'Master the controlled push-up first; land soft on the hands with a slight elbow bend to absorb the impact; reset before the next rep.', 'Chest', 'compound', 'bilateral'),
  ('Push-Up (feet elevated)', 'A standard push-up with the feet raised on a bench or box -- shifts more of the load onto the upper chest and shoulders compared to a flat push-up.', 'Keep the body in a straight line from head to heels; lower with control until the chest nears the floor; press back up evenly through both arms.', 'Chest', 'compound', 'bilateral'),
  ('Push-Up w/ Leg Lift (or Light DB Bench Press)', 'A standard push-up with one leg lifted off the ground (or, as a substitute, a light dumbbell bench press) -- the leg lift adds a core-stability and balance demand to the base push-up.', 'Keep the hips square, not rotating toward the lifted leg; keep the body in a straight line from head to heels; lower with control and press back up evenly.', 'Chest', 'compound', 'bilateral'),
  ('Scapular Retraction (band, light)', 'Pulling the shoulder blades together against a light resistance band, without significant arm movement -- isolates shoulder blade control, often used as shoulder-health prehab.', 'Focus the movement on squeezing the shoulder blades together, not just pulling with the arms; keep the movement small and controlled; avoid shrugging the shoulders up.', 'Shoulders', 'accessory', 'bilateral'),
  ('Seated 90/90 Breathing + Pelvic Tilt', 'Seated positional breathing (full exhales) combined with gentle pelvic tilts -- resets core and pelvis position through breath and small controlled movement.', 'Exhale fully and let the ribs settle down, not flare up; keep the pelvic tilts small and controlled, led by the breath rather than the hip flexors.', 'Core', 'mobility', 'bilateral'),
  ('Single-Leg Band Row', 'A Row performed with a resistance band while balancing on one leg -- combines a back-strengthening pull with a single-leg stability challenge.', 'Keep the standing knee soft and the torso stable as you row; drive the elbow back rather than just curling the band in; switch legs to balance the work.', 'Back', 'compound', 'per_leg'),
  ('Single-Leg Band Tricep Pushdown', 'A Tricep Pushdown performed with a band while balancing on one leg -- combines a triceps isolation movement with a single-leg stability challenge.', 'Keep the elbows pinned at the sides and the standing leg stable; extend fully without locking out hard; switch legs to balance the work.', 'Triceps', 'accessory', 'per_leg'),
  ('Single-Leg Bent-Over Row', 'A Row performed hinged forward while balancing on one leg (the other extended behind for counterbalance) -- combines a back row with a single-leg balance and hamstring challenge.', 'Keep the torso and extended leg roughly in line, forming a T-shape; drive the elbow back on the row; keep the standing knee soft, not locked.', 'Back', 'compound', 'per_leg'),
  ('Single-Leg Calf Raise', 'A Calf Raise performed on one leg at a time -- doubles the load on the working calf compared to a two-leg raise.', 'Rise all the way onto the toes with control, pause briefly at the top; lower slowly rather than dropping; use light support for balance if needed.', 'Calves', 'accessory', 'per_leg'),
  ('Single-Leg DB Bicep Curl', 'A Bicep Curl performed while balancing on one leg -- adds a stability challenge to the basic arm isolation movement.', 'Keep the standing leg soft, not locked; curl with strict form -- elbow pinned, no torso swing; switch legs to balance the work.', 'Biceps', 'accessory', 'per_leg'),
  ('Single-Leg DB Chest Fly (standing)', 'A standing Chest Fly performed while balancing on one leg -- combines a chest isolation movement with a single-leg stability challenge.', 'Keep a slight bend in the elbows throughout the fly; keep the standing leg stable and the torso upright; switch legs to balance the work.', 'Chest', 'accessory', 'per_leg'),
  ('Single-Leg DB Shoulder Press', 'A Shoulder Press performed while balancing on one leg -- combines an overhead press with a single-leg stability challenge.', 'Brace the core so the low back doesn''t overarch as the weight goes overhead; keep the standing leg stable; switch legs to balance the work.', 'Shoulders', 'compound', 'per_leg'),
  ('Single-Leg Face Pull', 'A Face Pull performed while balancing on one leg -- combines a rear-shoulder pulling movement with a single-leg stability challenge.', 'Pull toward the face with the elbows high; keep the standing leg stable through the pull; switch legs to balance the work.', 'Shoulders', 'accessory', 'per_leg'),
  ('Single-Leg Front Raise', 'A Front Raise performed while balancing on one leg -- combines a front-shoulder isolation movement with a single-leg stability challenge.', 'Raise to roughly shoulder height without swinging the torso; keep the standing leg stable; switch legs to balance the work.', 'Shoulders', 'accessory', 'per_leg'),
  ('Single-Leg Glute Bridge', 'A Glute Bridge performed with one leg extended, all the work on the other -- doubles the demand on the working glute compared to a two-leg bridge.', 'Keep the hips level, not dropping toward the extended-leg side; drive through the working heel and squeeze the glute at the top; lower under control.', 'Glutes', 'accessory', 'per_leg'),
  ('Single-Leg Glute Bridge, controlled', 'The Single-Leg Glute Bridge performed with a deliberately slow, controlled tempo on both the lift and the lower.', 'Lift through a 2-3 count and lower through the same; keep the hips level throughout, not rotating toward the extended leg; squeeze the glute hard at the top.', 'Glutes', 'accessory', 'per_leg'),
  ('Single-Leg Hip Hinge, controlled', 'A Romanian-Deadlift-style hip hinge performed on one leg, with a deliberately slow, controlled tempo -- builds single-leg hamstring/glute strength and balance together.', 'Keep the hips square, not opening up toward the standing leg; push the hips back while the extended leg reaches behind for balance; keep a flat back throughout.', 'Hamstrings', 'compound', 'per_leg'),
  ('Single-Leg Hip Thrust', 'A Hip Thrust performed with one leg extended, all the work on the other -- doubles the demand on the working glute compared to a two-leg thrust.', 'Keep the hips level, not dropping toward the extended-leg side; drive through the working heel and squeeze the glute hard at the top; lower under control.', 'Glutes', 'compound', 'per_leg'),
  ('Single-Leg Hip Thrust (loaded)', 'The Single-Leg Hip Thrust performed with added weight across the hips -- more resistance on the same single-leg glute movement.', 'Keep the hips level throughout, even under the added load; drive through the working heel and squeeze the glute hard at the top.', 'Glutes', 'compound', 'per_leg'),
  ('Single-Leg Lateral Raise', 'A Lateral Raise performed while balancing on one leg -- combines a side-shoulder isolation movement with a single-leg stability challenge.', 'Lead with the elbows, raising to roughly shoulder height; keep the standing leg stable throughout; switch legs to balance the work.', 'Shoulders', 'accessory', 'per_leg'),
  ('Single-Leg Overhead Press', 'An Overhead Press performed while balancing on one leg -- combines a shoulder press with a single-leg stability and core-control challenge.', 'Brace the core so the low back doesn''t overarch; keep the standing leg stable through the whole press; switch legs to balance the work.', 'Shoulders', 'compound', 'per_leg'),
  ('Single-Leg RDL', 'A Romanian Deadlift performed on one leg -- hinging forward with the working leg while the other extends back for counterbalance -- builds hamstring/glute strength and balance together.', 'Keep the hips square, not opening up toward the standing leg; push the hips back while the extended leg reaches behind; keep a flat back and feel the stretch through the hamstring before standing back up.', 'Hamstrings', 'compound', 'per_leg'),
  ('Single-Leg RDL (loaded)', 'The Single-Leg RDL performed holding added weight -- more resistance on the same single-leg hip-hinge movement.', 'Keep the same square hips and flat back as the bodyweight version; keep the weight close to the standing leg throughout the hinge.', 'Hamstrings', 'compound', 'per_leg'),
  ('Single-Leg RDL to Hop', 'A Single-Leg RDL that finishes by driving up into a small hop on the working leg -- adds a power component to the base balance-and-hinge movement.', 'Master the controlled RDL before adding the hop; land soft with a bent knee, absorbing the landing; keep the hips square throughout.', 'Hamstrings', 'compound', 'per_leg'),
  ('Single-Leg Reach', 'Balancing on one leg while reaching the free leg (or arms) forward, side, or back -- builds single-leg balance and hip control through reaching patterns.', 'Keep the standing knee soft, not locked; reach only as far as balance allows without wobbling badly; switch legs to balance the work.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Single-Leg Reach (loaded)', 'The Single-Leg Reach performed holding added weight -- more challenge on the same single-leg balance-and-reach movement.', 'Keep the same controlled balance as the unloaded version; don''t let the added weight pull you off balance -- reduce the reach distance if needed.', 'Balance/Mobility', 'accessory', 'per_leg'),
  ('Standing Glute Kickback', 'Standing and extending one leg back against resistance (band, cable, or bodyweight) -- isolates the glute through hip extension.', 'Keep the movement coming from the hip, not the low back arching to add range; squeeze the glute hard at the top of the kick; control the return.', 'Glutes', 'accessory', 'per_leg'),
  ('Step-Up (loaded)', 'A Step-Up onto a box performed holding added weight -- more resistance on the basic single-leg step-up pattern.', 'Step up through the whole foot on the box, not pushing off the trailing leg; keep the working knee tracking over the toes; control the step back down.', 'Quads', 'compound', 'per_leg'),
  ('Sumo RDL', 'A Romanian Deadlift performed with a wide stance and toes turned out -- shifts more of the work onto the inner thighs alongside the hamstrings and glutes.', 'Take a wide stance with toes turned out; hinge at the hips keeping a flat back; feel a stretch through the inner thighs and hamstrings before driving the hips forward to stand.', 'Hamstrings', 'compound', 'bilateral'),
  ('Sumo Squat', 'A squat performed with a wide stance and toes turned out -- shifts more of the work onto the inner thighs and glutes compared to a standard squat.', 'Take a wide stance with toes turned out; sit straight down between the legs keeping the torso upright; keep the knees pushed out in line with the toes throughout.', 'Quads', 'compound', 'bilateral'),
  ('Supported Squat (chair-assisted, partial range)', 'A squat performed holding onto a stable support, through a shortened, comfortable range -- an accessible entry point for building squat strength and confidence.', 'Use the support for balance, not to pull yourself up; squat only as deep as feels controlled and pain-free; keep the chest tall throughout.', 'Quads', 'compound', 'bilateral'),
  ('Wall Push-Up', 'A Push-Up performed standing, hands against a wall -- the most accessible version of the push-up pattern, reducing the load compared to a floor push-up.', 'Keep the body in a straight line from head to heels, not piking at the hips; lower with control until the chest nears the wall; press back to start.', 'Chest', 'compound', 'bilateral'),
  ('Band Lat Pulldown / Assisted Pull-Up', 'A Lat Pulldown performed with a band, or a Pull-Up assisted by a band looped over the bar -- either way, a scaled-down version of the vertical pulling pattern that builds toward an unassisted pull-up.', 'Pull with the lats and elbows driving down, not just the arms; control the return to a full stretch each rep; keep the core braced, not swinging for momentum.', 'Back', 'compound', 'bilateral'),
  ('Band Pull-Apart', 'Holding a resistance band with both hands and pulling it apart until it touches the chest -- a simple, high-rep movement for rear-shoulder and upper-back health.', 'Keep the arms fairly straight throughout; lead with the shoulder blades squeezing together, not just the hands moving; control the band back to start.', 'Shoulders', 'accessory', 'bilateral'),
  ('Band Pull-Apart (heavier band)', 'The Band Pull-Apart using a heavier resistance band -- same movement, more resistance.', 'Keep the same straight-arm, shoulder-blade-led form as a lighter band -- don''t let the heavier band shorten the range or turn it into a jerky pull.', 'Shoulders', 'accessory', 'bilateral'),
  ('Band Pull-Apart (higher volume)', 'The Band Pull-Apart performed for a higher rep count -- same movement, more volume to build shoulder endurance.', 'Keep the same quality of shoulder-blade squeeze on the last rep as the first; don''t let fatigue turn it into a small, sloppy pull.', 'Shoulders', 'accessory', 'bilateral'),
  ('Band Pull-Apart + External Rotation', 'The Band Pull-Apart combined with an external rotation of the shoulders (rotating the forearms up and back) at the end of the pull -- adds a rotator-cuff component to the base pull-apart.', 'Pull the band apart first, then rotate the forearms up and back keeping the elbows roughly in place; control the return through both parts of the movement.', 'Shoulders', 'accessory', 'bilateral'),
  ('Barbell/DB Row', 'A hinged-over Row performed with a barbell or dumbbells -- a foundational back-strengthening movement.', 'Hinge at the hips with a flat back roughly parallel to the floor, core braced; row the weight to the lower ribs by driving the elbows back; lower under control without the torso swinging.', 'Back', 'compound', 'bilateral'),
  ('Bulgarian Split Squat', 'A Split Squat with the rear foot elevated on a bench -- increases the range of motion and single-leg demand compared to a standard split squat.', 'Keep most of the weight on the front leg -- the back foot is for balance, not driving the movement; lower until the front thigh is roughly parallel to the floor; drive through the front foot to stand.', 'Quads', 'compound', 'per_leg'),
  ('Chest Press (DB/Machine)', 'A Chest Press performed with dumbbells or on a machine -- a foundational chest-pressing movement, whichever equipment is set up.', 'Set the shoulder blades back and down before pressing; lower under control to chest level; press up evenly, without locking the elbows out hard.', 'Chest', 'compound', 'bilateral'),
  ('DB Ball Chest Press', 'A Chest Press performed lying on a stability ball rather than a bench -- adds a core-stability demand to the basic chest press.', 'Keep the hips lifted and stable on the ball throughout; press evenly through both arms; lower under control to chest level.', 'Chest', 'compound', 'bilateral'),
  ('DB/Barbell Bench Press', 'A Bench Press performed with dumbbells or a barbell -- a foundational chest-pressing movement, whichever equipment is set up.', 'Set the shoulder blades back and down before unracking/pressing; lower under control to the chest; drive up evenly through both sides.', 'Chest', 'compound', 'bilateral'),
  ('Deadlift (conv./trap bar)', 'A fundamental hip-hinge lift that picks a load up off the floor with either a conventional barbell or a trap bar -- builds total-body pulling strength through the posterior chain.', 'Set the hips back with a flat back and the bar/handles close to the shins; brace the core before pulling; drive through the floor and extend the hips to stand tall, then reverse the motion under control.', 'Hamstrings', 'compound', 'bilateral'),
  ('Incline DB Press', 'A Chest Press performed with dumbbells on an inclined bench -- shifts more emphasis to the upper chest and front shoulder compared to a flat press.', 'Set the bench at a moderate incline, not too steep; lower under control to the upper chest; press up evenly through both arms.', 'Chest', 'compound', 'bilateral'),
  ('Pull-Up / Lat Pulldown', 'A Pull-Up, or the Lat Pulldown machine version for those building toward one -- a foundational vertical-pulling movement for the back.', 'Pull with the lats and elbows driving down, not just the arms; control the return to a full stretch; avoid swinging or kipping for momentum.', 'Back', 'compound', 'bilateral'),
  ('Romanian Deadlift', 'A fundamental hip-hinge lift -- pushing the hips back with a flat back and a soft knee bend, lowering the weight along the legs -- builds the hamstrings and glutes through a stretch-focused range.', 'Push the hips straight back, not squatting down; keep a flat back and the weight close to the legs; feel a stretch through the hamstrings before driving the hips forward to stand.', 'Hamstrings', 'compound', 'bilateral'),
  ('Ab/Core: 90/90 Breathing + Bird Dog', '90/90 positional breathing (hips and knees stacked at 90 degrees, full exhales) paired with Bird Dogs -- resets core/rib position through breath, then applies it to the anti-rotation movement.', 'On the breathing, exhale fully and let the ribs settle down; on the Bird Dog, keep the hips level and low back still, moving slow and controlled.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Bird Dog + Glute Bridge March', 'A combo set: Bird Dogs paired with a Glute Bridge held while marching the knees up one at a time -- hits anti-rotation core control and glute-focused hip stability together.', 'On the Bird Dog, keep the hips level and the low back still; on the bridge march, keep the hips level and squeezed as each knee lifts, not dipping.', 'Core', 'accessory', 'per_side'),
  ('Ab/Core: Dead Bug + Leg Raise', 'Dead Bug paired with a straight-leg raise -- combines the anti-extension Dead Bug pattern with a leg-lowering core challenge.', 'Press the low back flat into the floor and keep it there through both movements; lower the leg only as far as that contact holds.', 'Core', 'accessory', 'per_side')
) as v(name, description, cues, muscle_group, movement_type, laterality)
where e.name = v.name;
